import React from 'react';
import { Link } from 'react-router-dom';

export default function Home(){
  return (
    <section id="home" className="hero">
      <div className="container hero-inner">
        <div className="hero-copy">
          <h1>Your Space Can Now Listen, Learn and Respond!</h1>
          <p className="lead">Smart home & building automation solutions that make everyday living intelligent, efficient and secure.</p>
          <Link className="btn" to="/products">Our Products</Link>
        </div>
        <div className="hero-media">
          <img src="https://images.unsplash.com/photo-1506765515384-028b60a970df?q=80&w=1200&auto=format&fit=crop&ixlib=rb-4.0.3&s=placeholder" alt="Smart home"/>
        </div>
      </div>
    </section>
  );
}
